				if rng.Intn(4) == 0 {
					runtime.Gosched()
				}
				req := request{operation: operationDequeue}
				if clientID < producers {
					req = request{
						operation: operationEnqueue,
						value:     uint64(trial+1)<<48 | uint64(clientID)<<32 | uint64(opIndex),
