    51	std::vector<double> longestPathDag(const Graph& g, const std::vector<int>& order) {
    52	    std::map<int, double> dist;
    53	    for (const auto& kv : g.nodeMap()) {
    54	        dist[kv.first] = kv.second->weight;
    55	    }
    56	
    57	    for (std::size_t i = 0; i < order.size(); ++i) {
    58	        int id = order[i];
    59	        std::vector<int> nb = g.neighbors(id);
    60	        for (std::size_t j = 0; j < nb.size(); ++j) {
    61	            int to = nb[j];
    62	            Node* tn = g.node(to);
    63	            if (tn == nullptr) continue;
    64	            double cand = dist[id] + tn->weight;
    65	            if (cand > dist[to]) {
    66	                dist[to] = cand;
    67	            }
    68	        }
    69	    }
    70	
    71	    std::vector<double> out;
    72	    for (const auto& kv : g.nodeMap()) {
    73	        out.push_back(dist[kv.first]);
    74	    }
    75	    return out;
    76	}
    77	
    78	double criticalPath(const Graph& g) {
    79	    std::vector<int> order = topoSortKahnSlow(g);
    80	    std::vector<double> dist = longestPathDag(g, order);
    81	    double best = 0.0;
    82	    for (std::size_t i = 0; i < dist.size(); ++i) {
    83	        if (dist[i] > best) best = dist[i];
    84	    }
    85	    return best;
    86	}
    87	
    88	std::vector<int> bfsLevels(const Graph& g, int root) {
    89	    std::map<int, int> level;
    90	    std::vector<int> frontier;
    91	    frontier.push_back(root);
    92	    level[root] = 0;
    93	
    94	    while (!frontier.empty()) {
    95	        int id = frontier.front();
    96	        frontier.erase(frontier.begin());
    97	
    98	        std::vector<int> nb = g.neighbors(id);
    99	        for (std::size_t i = 0; i < nb.size(); ++i) {
   100	            int to = nb[i];
   101	            if (level.count(to) == 0) {
   102	                level[to] = level[id] + 1;
   103	                frontier.push_back(to);
   104	            }
   105	        }
   106	    }
   107	
   108	    std::vector<int> out;
   109	    for (const auto& kv : g.nodeMap()) {
   110	        if (level.count(kv.first)) {
   111	            out.push_back(level[kv.first]);
   112	        } else {
   113	            out.push_back(-1);
   114	        }
   115	    }
   116	    return out;
   117	}
